class Solution {
public:
    int maxWidthRamp(vector<int>& nums) {
        int n = nums.size();
        vector<int> st;
        st.reserve(n);
        for (int i = 0; i < n; ++i) {
            if (st.empty() || nums[i] < nums[st.back()]) {
                st.push_back(i);
            }
        }
        int best = 0;
        for (int j = n - 1; j >= 0; --j) {
            while (!st.empty() && nums[st.back()] <= nums[j]) {
                int i = st.back();
                st.pop_back();
                if (j - i > best) best = j - i;
            }
        }
        return best;
    }
};
